module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

always @(*) begin
    r = 32'b0;
    zero = 1'b0;
    carry = 1'b0;
    negative = 1'b0;
    overflow = 1'b0;
    flag = 1'b0;

    case (aluc)
        ADD: begin
            r = a + b;
            carry = (a[31] & b[31]) | (~a[31] & r[31]);
            negative = r[31];
            overflow = (a[31] & b[31] & ~r[31]) | (~a[31] & ~b[31] & r[31]);
        end
        ADDU: begin
            r = a + b;
            carry = (a[31] & b[31]) | (~a[31] & r[31]);
        end
        SUB: begin
            r = a - b;
            carry = (~a[31] & b[31]) | (a[31] & ~r[31]);
            negative = r[31];
            overflow = (a[31] & ~b[31] & ~r[31]) | (~a[31] & b[31] & r[31]);
        end
        SUBU: begin
            r = a - b;
            carry = (~a[31] & b[31]) | (a[31] & ~r[31]);
        end
        AND: r = a & b;
        OR: r = a | b;
        XOR: r = a ^ b;
        NOR: r = ~(a | b);
        SLT: begin
            r = $signed(a) < $signed(b) ? 32'b1 : 32'b0;
            flag = 1'b1;
        end
        SLTU: begin
            r = a < b ? 32'b1 : 32'b0;
            flag = 1'b1;
        end
        SLL: r = {a << b[4:0], 32'b0};
        SRL: r = {32'b0, a >> b[4:0]};
        SRA: r = {a[31], a >> b[4:0]};
        SLLV: r = {a << (b & 31), 32'b0};
        SRLV: r = {32'b0, a >> (b & 31)};
        SRAV: r = {a[31], a >> (b & 31)};
        LUI: r = {b, 16'b0};
        default: r = 32'b0;
    endcase

    zero = (r == 32'b0);
end

endmodule
